package com.bank.history;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ImmutableListDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Transaction> backing = new ArrayList<>();
        backing.add(new Transaction("TXN-1", "SAV2001", new BigDecimal("50000")));

        // 1) unmodifiableList = VIEW. Mutating 'backing' leaks through.
        List<Transaction> view = Collections.unmodifiableList(backing);
        backing.add(new Transaction("TXN-2", "CUR3001", new BigDecimal("10000")));
        log.warning(() -> "unmodifiable VIEW leaked backing change, size=" + view.size()); // 2!

        try { view.add(new Transaction("X","X",BigDecimal.ONE)); }
        catch (UnsupportedOperationException e) { log.info("view.add blocked"); }

        // 2) List.copyOf = INDEPENDENT immutable snapshot. Backing changes do NOT leak.
        List<Transaction> snapshot = List.copyOf(backing);
        backing.add(new Transaction("TXN-3", "SAV2001", new BigDecimal("999")));
        log.info(() -> "copyOf SNAPSHOT size stayed = " + snapshot.size()); // unchanged

        // 3) Structural immutability is NOT deep: element is immutable here, so safe.
        Transaction first = snapshot.get(0);
        log.info(() -> "Element is immutable type, no setter to tamper: " + first);
    }
}

