// IMMUTABLE element type -> gives DEEP immutability when stored in an immutable list.
final class Transaction {
    private final String id;
    private final String accountId;
    private final BigDecimal amount;
    Transaction(String id, String accountId, BigDecimal amount) {
        this.id = id; this.accountId = accountId; this.amount = amount;
    }
    public String toString() { return id + " " + accountId + " Rs." + amount; }
}
